/**
 * KRISLYNX visualization system.
 *
 * Every visualization server-renders its complete content (labels, panels, legends) as HTML, so it reads
 * without JavaScript, without motion and to screen readers. src/client/viz.ts adds selection (click, hover on
 * fine pointers, focus, arrow keys), path lighting (root[data-active]) and one-time autoplay. All motion is
 * CSS (no Lottie runtime is available offline; see docs/VISUAL-TRANSFORMATION.md → Animation inventory) and
 * stops under prefers-reduced-motion. CSP forbids inline styles, so geometry-dependent CSS is generated by
 * vizCss() from the same constants that draw the SVG.
 *
 * Content rules: technologies derive from config/technology.ts; products and statuses from config/products.ts;
 * EduLynx modules from config/products.ts; anything illustrative is labelled and contains no numbers.
 */
import type { SafeHtml } from "@kx/jsx-runtime";
import { techLayers } from "../config/technology";
import { lifecycle } from "../config/lifecycle";
import { edulynx, products, statusLabel } from "../config/products";
import { serviceFlows, services } from "../config/services";
import { systemFlow, systemNodes } from "../config/system";
import { caseStudies } from "../config/work";
import { StatusBadge, TechLabel } from "./ui";
import { Picture } from "./media";

const pad = (n: number): string => String(n).padStart(2, "0");

function Fig(props: { n?: string; title: string }): SafeHtml {
  return (
    <p class="fig-label" aria-hidden="true">
      <span>{props.n ? `FIG. ${props.n}` : "SYSTEM"}</span>
      <span>{props.title}</span>
    </p>
  );
}

/** Technologies for a system node, derived from the approved sources (never typed by hand). */
export function techFor(keys: readonly string[]): string[] {
  return keys.flatMap((k) => techLayers.find((l) => l.key === k)?.items ?? []);
}

/* ========================================================== SYSTEM MAP */

const W = 600;
const H = 440;
const C = { x: 300, y: 220 };
export const sysPos = systemNodes.map((n, i) => {
  const a = ((-90 + 60 * i) * Math.PI) / 180;
  return { key: n.key, x: Math.round(C.x + 215 * Math.cos(a)), y: Math.round(C.y + 158 * Math.sin(a)) };
});
const curve = (x: number, y: number): string => {
  const mx = (C.x + x) / 2 + (y - C.y) * 0.18;
  const my = (C.y + y) / 2 - (x - C.x) * 0.18;
  return `M${C.x} ${C.y} Q${Math.round(mx)} ${Math.round(my)} ${x} ${y}`;
};

function SystemLines(): SafeHtml {
  return (
    <svg class="smap__svg" viewBox={`0 0 ${W} ${H}`} aria-hidden="true" focusable="false">
      <ellipse class="smap__orbit" cx={String(C.x)} cy={String(C.y)} rx="215" ry="158" />
      <ellipse class="smap__orbit smap__orbit--inner" cx={String(C.x)} cy={String(C.y)} rx="120" ry="88" />
      {sysPos.map((p, i) => {
        const n = systemNodes[i];
        return (
          <g class={`smap__link smap__link--${p.key} tone--${n?.tone ?? "blue"}`}>
            <path class="smap__path" d={curve(p.x, p.y)} />
            <path class={`smap__comet smap__comet--i${i}`} d={curve(p.x, p.y)} />
          </g>
        );
      })}
    </svg>
  );
}

/**
 * variant "hero": ambient assembly + links into the system section.
 * variant "full": explorer with panels (What it is / What KrisLynx does / Related technology).
 */
export function SystemMap(props: { variant: "hero" | "full" }): SafeHtml {
  const hero = props.variant === "hero";
  const core = (
    <div class="smap__core" aria-hidden="true">
      <span class="mono">SYSTEM CORE</span>
      <strong>KrisLynx</strong>
    </div>
  );
  if (hero) {
    return (
      <figure class="smap smap--hero" data-map="" aria-labelledby="smap-hero-cap">
        <div class="smap__stage" data-parallax="">
          <SystemLines />
          {core}
          {systemNodes.map((n, i) => (
            <a href={`#sys-tab-${n.key}`} class={`smap__node smap__node--${n.key} smap__node--i${i} tone--${n.tone}`} data-node={n.key} data-select={`sys-tab-${n.key}`}>
              <span class="smap__dot" aria-hidden="true"></span>
              {n.label}
            </a>
          ))}
        </div>
        <ol class="smap__flow" aria-label="How work moves through a system">
          {systemFlow.map((s, i) => (
            <li class={`smap__flow-step smap__flow-step--i${i}`}>
              <span class="mono" aria-hidden="true">
                {pad(i + 1)}
              </span>
              {s}
            </li>
          ))}
        </ol>
        <figcaption id="smap-hero-cap" class="visually-hidden">
          The KrisLynx system: products, software, AI, data, cloud and operations connected to one engineering core. Work moves from input through processing and intelligence to a working system and a real outcome.
        </figcaption>
      </figure>
    );
  }
  return (
    <div class="smap smap--full viz" data-viz="system" data-active={systemNodes[0]?.key}>
      <Fig n="01" title="The KrisLynx system — select a node" />
      <div class="smap__grid">
        <div class="smap__stage" role="tablist" aria-label="System components">
          <SystemLines />
          {core}
          {systemNodes.map((n, i) => (
            <button
              type="button"
              role="tab"
              class={`smap__node smap__node--${n.key} smap__node--i${i} tone--${n.tone}`}
              id={`sys-tab-${n.key}`}
              data-key={n.key}
              aria-controls={`sys-panel-${n.key}`}
              aria-selected={i === 0 ? "true" : "false"}
              tabindex={i === 0 ? "0" : "-1"}
            >
              <span class="smap__dot" aria-hidden="true"></span>
              {n.label}
            </button>
          ))}
        </div>
        <div class="smap__panels">
          {systemNodes.map((n, i) => {
            const tech = n.products ? products.map((p) => `${p.name} — ${statusLabel[p.status]}`) : techFor(n.tech);
            return (
              <section class={`smap__panel glass viz-panel tone--${n.tone}`} id={`sys-panel-${n.key}`} role="tabpanel" aria-labelledby={`sys-tab-${n.key}`} data-viz-panel={n.key} data-inactive={i === 0 ? undefined : ""}>
                <TechLabel index={pad(i + 1)} label={n.label} />
                <dl class="smap__facts">
                  <div>
                    <dt>What it is</dt>
                    <dd>{n.what}</dd>
                  </div>
                  <div>
                    <dt>What KrisLynx does</dt>
                    <dd>{n.does}</dd>
                  </div>
                  <div>
                    <dt>{n.products ? "Products" : "Related technology"}</dt>
                    <dd>
                      <ul class="chips">
                        {tech.map((t) => (
                          <li>{t}</li>
                        ))}
                      </ul>
                    </dd>
                  </div>
                </dl>
              </section>
            );
          })}
        </div>
      </div>
    </div>
  );
}

