/* ============================================================ DATA FLOW */

const dfStages = [
  { key: "input", name: "Input", text: "People and systems produce events: a form submitted, attendance marked, a file uploaded." },
  { key: "data", name: "Data", text: "Events become records in one shared model, so every part of the system reads the same truth." },
  { key: "processing", name: "Processing", text: "Business rules validate, calculate and route: fees due, permissions checked, reports assembled." },
  { key: "intelligence", name: "Intelligence", text: "Where it earns its place, AI summarises and flags patterns across records — with reasons attached." },
  { key: "decision", name: "Decision", text: "A person with the right role reviews and decides. The system records who decided what." },
  { key: "action", name: "Action", text: "The outcome goes back into operations: a reminder sent, a report filed, a workflow moved on." },
];
/** Signal lanes: type, label, start stage index, end stage index. */
const dfLanes = [
  { key: "app", label: "Application data", tone: "blue", from: 0, to: 2 },
  { key: "sys", label: "System data", tone: "cyan", from: 1, to: 4 },
  { key: "intel", label: "Intelligence", tone: "violet", from: 2, to: 4 },
  { key: "out", label: "Output", tone: "mint", from: 4, to: 5 },
] as const;

export function DataFlow(): SafeHtml {
  const colX = (i: number): number => 50 + i * 100;
  return (
    <div class="df viz" data-viz="dataflow" data-active="input">
      <Fig n="04" title="Data flow — select a stage" />
      <div class="df__stage">
        <svg class="df__svg" viewBox="0 0 600 150" aria-hidden="true" focusable="false">
          {dfStages.map((_, i) => (
            <line class={`df__col df__col--i${i}`} x1={String(colX(i))} y1="8" x2={String(colX(i))} y2="142" />
          ))}
          {dfLanes.map((l, i) => {
            const y = 30 + i * 30;
            const d = `M${colX(l.from)} ${y} H${colX(l.to)}`;
            return (
              <g class={`df__lane tone--${l.tone}`}>
                <path class="df__path" d={d} />
                <path class={`df__comet df__comet--i${i}`} d={d} />
                <circle class="df__node" cx={String(colX(l.from))} cy={String(y)} r="3.5" />
                <circle class="df__node" cx={String(colX(l.to))} cy={String(y)} r="3.5" />
              </g>
            );
          })}
        </svg>
        <div class="df__tabs" role="tablist" aria-label="Data flow stages">
          {dfStages.map((s, i) => (
            <button type="button" role="tab" class={`df__tab df__tab--i${i}`} id={`df-tab-${s.key}`} data-key={s.key} aria-controls={`df-panel-${s.key}`} aria-selected={i === 0 ? "true" : "false"} tabindex={i === 0 ? "0" : "-1"}>
              <span class="mono" aria-hidden="true">
                {pad(i + 1)}
              </span>
              {s.name}
            </button>
          ))}
        </div>
      </div>
      <div class="df__foot">
        <div class="df__panels">
          {dfStages.map((s, i) => (
            <p class="df__panel viz-panel" id={`df-panel-${s.key}`} role="tabpanel" aria-labelledby={`df-tab-${s.key}`} data-viz-panel={s.key} data-inactive={i === 0 ? undefined : ""}>
              <strong>{s.name}.</strong> {s.text}
            </p>
          ))}
        </div>
        <ul class="df__legend" aria-label="Signal types">
          {dfLanes.map((l) => (
            <li class={`tone--${l.tone}`}>
              <span class="df__swatch" aria-hidden="true"></span>
              {l.label}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

