/* ================================================= generated geometry CSS */

export function vizCss(): string {
  const r: string[] = [];
  for (const p of sysPos) r.push(`.smap__node--${p.key}{left:${((p.x / W) * 100).toFixed(2)}%;top:${((p.y / H) * 100).toFixed(2)}%}`);
  for (const n of systemNodes) r.push(`.smap[data-active="${n.key}"] .smap__link--${n.key} .smap__path{stroke:var(--tone);stroke-opacity:.95;stroke-width:2}.smap[data-active="${n.key}"] .smap__node--${n.key}{border-color:var(--tone);color:var(--text-hi)}`);
  const lit = (root: string, item: string, keys: readonly string[]): void => {
    keys.forEach((k, i) => r.push(keys.slice(0, i + 1).map((_, j) => `.${root}[data-active="${k}"] .${item}--i${j}`).join(",") + "{--lit:1}"));
  };
  lit("lf", "lf__stage", lifecycle.map((s) => s.key));
  lit("aip", "aip__step", aiSteps.map((s) => s.key));
  dfStages.forEach((s, i) => {
    r.push(`.df[data-active="${s.key}"] .df__tab--i${i}{--lit:1}`);
    r.push(`.df[data-active="${s.key}"] .df__col--i${i}{stroke-opacity:.8}`);
  });
  for (const k of opsKeys) r.push(`.edx[data-active="${k}"] .edx__flow-step--mod::after{content:" · ${edulynx.modules.find((m) => m.key === k)?.name ?? ""}"}`);
  r.push(`.edx[data-active="ai"] .edx__flow-step--ai{border-color:var(--violet);color:var(--text-hi);box-shadow:0 0 0 4px rgba(185,168,255,.12)}`);
  return r.join("\n") + "\n";
}

