/* ================================================== v3.1: TECH ARCHITECTURE */

/** Layer placement for each APPROVED technology item (technology.ts). A test asserts every item is placed once. */
export const archLayers = [
  { key: "interface", name: "Interface", note: "What people touch", from: ["frontend"], role: "Screens, forms and interactions — accessible and fast on real devices.", purpose: "Make the correct action the obvious one.", path: ["interface", "application", "api"] },
  { key: "application", name: "Application", note: "Business logic", pick: ["Python", "Flask", "Node.js"], role: "Rules, workflows, validation and permissions.", purpose: "Keep the rules in one place, and tested.", path: ["interface", "application", "api"] },
  { key: "api", name: "API", note: "How parts talk", pick: ["REST APIs"], role: "Stable, authenticated contracts between the parts of a system.", purpose: "Let each part change without breaking the others.", path: ["application", "api", "services"] },
  { key: "services", name: "Services", note: "Jobs and intelligence", pick: ["Background workers"], from: ["ai"], role: "Background jobs and AI: reports, reminders, assistants.", purpose: "Do slow or smart work away from the user's request.", path: ["api", "services", "data"] },
  { key: "data", name: "Data", note: "The organization's memory", from: ["data"], role: "One data model, audited writes, reporting.", purpose: "Every module reads the same truth.", path: ["services", "data", "infrastructure"] },
  { key: "infrastructure", name: "Infrastructure", note: "Where it runs", from: ["cloud"], role: "Hosting, delivery, automated releases and monitoring.", purpose: "Releases that are repeatable and uneventful.", path: ["data", "infrastructure"] },
] as const;
export function archItems(layer: (typeof archLayers)[number]): string[] {
  const fromLayers = "from" in layer && layer.from ? layer.from.flatMap((k) => techLayers.find((l) => l.key === k)?.items ?? []) : [];
  const picked = "pick" in layer && layer.pick ? layer.pick.filter((t) => techLayers.some((l) => (l.items as readonly string[]).includes(t))) : [];
  return [...picked, ...fromLayers];
}

/**
 * Six-layer architecture (V2.1). Disclosure pattern: every layer is a native button (aria-expanded) that
 * controls its own detail region, one open at a time (Interface by default). Selecting a layer propagates a
 * signal along its real dependency path; unrelated layers stay visible but quieter. Desktop: side panel.
 * Mobile: vertical accordion. No JS: every layer expanded.
 */
export function TechArchitecture(): SafeHtml {
  const sec = techLayers.find((l) => l.key === "security");
  const name = (k: string): string => archLayers.find((l) => l.key === k)?.name ?? k;
  return (
    <figure class="arch3" data-arch="" data-active="interface" aria-labelledby="arch3-cap">
      <Fig n="04" title="Reference architecture — select a layer" />
      <div class="arch3__grid">
        <div class="arch3__stack" role="group" aria-label="Architecture layers">
          <span class="arch3__signal" aria-hidden="true"></span>
          {archLayers.map((l, i) => (
            <>
              <h3 class={`arch3__h arch3__h--i${i}`}>
                <button type="button" class={`arch3__layer arch3__layer--${l.key}`} id={`arch-btn-${l.key}`} data-key={l.key} aria-expanded={i === 0 ? "true" : "false"} aria-controls={`arch-panel-${l.key}`}>
                  <span class="arch3__id mono" aria-hidden="true">
                    L{i}
                  </span>
                  <span class="arch3__name">{l.name}</span>
                  <span class="arch3__note">{l.note}</span>
                  <span class="arch3__state mono" aria-hidden="true">
                    {i === 0 ? "Selected" : ""}
                  </span>
                </button>
              </h3>
              <div class="arch3__panel" id={`arch-panel-${l.key}`} role="region" aria-labelledby={`arch-btn-${l.key}`} data-arch-panel={l.key} data-inactive={i === 0 ? undefined : ""}>
                <p class="arch3__path mono" aria-label={`Dependency path: ${l.path.map(name).join(", then ")}`}>
                  {l.path.map((k, n) => (
                    <>
                      {n ? <span aria-hidden="true"> → </span> : null}
                      <span class={k === l.key ? "is-self" : ""}>{name(k)}</span>
                    </>
                  ))}
                </p>
                <dl class="arch3__facts">
                  <div>
                    <dt>Responsibility</dt>
                    <dd>{l.role}</dd>
                  </div>
                  <div>
                    <dt>Engineering purpose</dt>
                    <dd>{l.purpose}</dd>
                  </div>
                  <div>
                    <dt>Technology we use here</dt>
                    <dd>
                      <ul class="chips">
                        {archItems(l).map((t) => (
                          <li>{t}</li>
                        ))}
                      </ul>
                    </dd>
                  </div>
                </dl>
              </div>
            </>
          ))}
        </div>
        {sec ? (
          <aside class="arch3__rail" aria-label="Security across every layer">
            <span class="mono">Security · every layer</span>
            <ul>
              {sec.items.map((t) => (
                <li>{t}</li>
              ))}
            </ul>
          </aside>
        ) : null}
      </div>
      <p class="arch3__trace" data-arch-trace inert>
        <button type="button" class="arch3__trace-btn" data-dir="down">
          Trace a request ↓ <span class="visually-hidden">from Interface to Infrastructure</span>
        </button>
        <button type="button" class="arch3__trace-btn" data-dir="up">
          Trace a response ↑ <span class="visually-hidden">from Infrastructure to Interface</span>
        </button>
      </p>
      <figcaption id="arch3-cap" class="viz-note">
        A reference architecture, not a specific client system. Every technology shown is one we work with; each project uses the subset it needs.
      </figcaption>
    </figure>
  );
}

/* ======================================================== v3.2: SCHOOL DAY */

const dayStops = [
  { time: "07:45", key: "attendance" }, { time: "09:00", key: "academics" }, { time: "11:00", key: "communication" },
  { time: "13:00", key: "finance" }, { time: "15:00", key: "exams" }, { time: "16:30", key: "reports" },
] as const;

/** An illustrative school day. Times are an example; every description is the module's published text. */
export function SchoolDay(): SafeHtml {
  const mods = dayStops.map((d) => ({ ...d, m: edulynx.modules.find((x) => x.key === d.key) }));
  return (
    <figure class="day viz" data-viz="day" data-active={mods[0]?.key} aria-labelledby="day-cap">
      <div class="day__list" role="tablist" aria-label="A school day in EduLynx ERP">
        {mods.map((d, i) => (
          <button type="button" role="tab" class={`day__stop day__stop--i${i}`} id={`day-tab-${d.key}`} data-key={d.key} aria-controls={`day-panel-${d.key}`} aria-selected={i === 0 ? "true" : "false"} tabindex={i === 0 ? "0" : "-1"}>
            <time class="day__time mono">{d.time}</time>
            <span class="day__name">{d.m?.name ?? d.key}</span>
          </button>
        ))}
      </div>
      <div class="day__panels">
        {mods.map((d, i) => (
          <section class="day__panel viz-panel" id={`day-panel-${d.key}`} role="tabpanel" aria-labelledby={`day-tab-${d.key}`} data-viz-panel={d.key} data-inactive={i === 0 ? undefined : ""}>
            <p class="day__panel-time mono">{d.time} · example time</p>
            <h3 class="display-3">{d.m?.name}</h3>
            <p>{`${d.time} is an example point in the school day where ${d.m?.name ?? d.key} work happens — on the same institution record every other stop uses.`}</p>
            <ul class="chips">
              {featuresOf(d.m?.body ?? "").slice(0, 4).map((f) => (
                <li>{f}</li>
              ))}
            </ul>
          </section>
        ))}
      </div>
      <p class="day__record">
        <span class="mono">One record</span> Every step writes to and reads from the same institution record.
      </p>
      <figcaption id="day-cap" class="viz-note">
        Illustrative school day — the times are examples; each step shows capabilities from the module’s published description.
      </figcaption>
    </figure>
  );
}

