export function vizCssV3(): string {
  const r: string[] = [];
  // interactive service diagrams: steps up to the selected one are lit
  ["product-engineering", "artificial-intelligence", "enterprise-software"].forEach((slug, i) => {
    const n = serviceFlows[slug]?.steps.length ?? 0;
    for (let j = 0; j < n; j++) r.push(Array.from({ length: j + 1 }, (_, k) => `.ssy__sys[data-active="ssy-${i}-${j}"] .ssy__step--i${k}`).join(",") + "{--lit:1}");
  });
  for (const n of hcNodes) r.push(`.hc__node--${n.key}{left:${n.x}%;top:${n.y}%}`);
  for (const p of orbitPos) r.push(`.orb__node--${p.key}{left:${p.x}%;top:${p.y}%}`);
  const rel = relatedModules();
  for (const k of orbitKeys) {
    const near = rel[k] ?? [];
    if (near.length) {
      r.push(near.map((j) => `.orb[data-active="${k}"] .orb__node--${j}`).join(",") + "{border-color:var(--orb-near);color:var(--text);background:#f3fcf7}");
      r.push(near.map((j) => `.orb[data-active="${k}"] .orb__spoke--${j}`).join(",") + "{stroke:var(--orb-near);stroke-opacity:1;stroke-width:.6}");
    }
    r.push(`.orb[data-active="${k}"] .orb__spoke--${k}{stroke:var(--orb-hot);stroke-opacity:1;stroke-width:1.1}`);
  }
  for (const n of hcNodes) r.push(`.hc[data-active="${n.key}"] .hc__note--${n.key}{display:block}.hc[data-active="${n.key}"] .hc__note--default{display:none}.hc[data-active="${n.key}"] .hc__link--${n.key} .hc__path{stroke-opacity:.95;stroke-width:.7}.hc[data-active="${n.key}"] .hc__node--${n.key}{border-color:var(--tone);background:rgba(18, 22, 20,.98);box-shadow:0 0 0 5px color-mix(in srgb,var(--tone) 16%,transparent)}`);
  // related paths: AI depends on data; applications carry people; products sit on data + apps
  const deps: Record<string, string[]> = { ai: ["data"], apps: ["people"], people: ["apps"], products: ["apps", "data"], data: ["ai", "products"] };
  for (const [k, ds] of Object.entries(deps)) r.push(ds.map((d) => `.hc[data-active="${k}"] .hc__link--${d} .hc__path`).join(",") + "{stroke-opacity:.7;stroke-width:.5}");
  r.push(`.hc[data-active="products"] .hc__frag--a{border-color:rgba(168,245,208,.55);box-shadow:0 0 0 1px rgba(168,245,208,.25),0 24px 50px -24px rgba(0,0,0,.8)}`);
  r.push(`.hc[data-active="ai"] .hc__frag--b{border-color:rgba(200,184,255,.6)}`);
  r.push(`.hc[data-active="people"] .hc__atmos{opacity:1}`);
  // V2.1 architecture: grid rows, dependency propagation, signal travel (desktop)
  const idx = (k: string): number => archLayers.findIndex((l) => l.key === k);
  // desktop only: layers occupy rows 1–6 beside the detail column; on mobile DOM order makes each panel open under its layer
  r.push("@media (min-width:64rem){" + archLayers.map((_l, i) => `.js .arch3__h--i${i}{grid-row:${i + 1}}`).join("") + "}");
  r.push("@media (scripting:enabled) and (min-width:64rem){" + archLayers.map((_l, i) => `.arch3__h--i${i}{grid-row:${i + 1}}`).join("") + "}");
  for (const l of archLayers) {
    l.path.forEach((k, n) => r.push(`.arch3[data-active="${l.key}"] .arch3__layer--${k}{--on:1;transition-delay:${n * 110}ms}`));
    const a = idx(l.path[0] ?? l.key), b = idx(l.path[l.path.length - 1] ?? l.key);
    r.push(`@keyframes arch-sig-${l.key}{0%{top:calc(${a} * var(--arch-step) + var(--arch-mid));opacity:0}12%{opacity:1}88%{opacity:1}100%{top:calc(${b} * var(--arch-step) + var(--arch-mid));opacity:0}}`);
    r.push(`@media (prefers-reduced-motion: no-preference){.arch3[data-active="${l.key}"] .arch3__signal{animation:arch-sig-${l.key} ${260 + (b - a) * 180}ms var(--ease-out-kx) both}}`);
  }
  return r.join("\n") + "\n";
}
